catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == '') {
       g_form.setDisplay('geo',true);
       g_form.setDisplay('company',true);
       g_form.setDisplay('country',true);
       g_form.setMandatory('alternate_buyer',false)
	   g_form.setMandatory('first_payment_approval_display',false)
       return;
    }
	setToHiden();

    if (newValue == '0' || newValue == '1') {
       //display variables for tab 1
       g_form.setDisplay('geo',true);
       g_form.setDisplay('company',true);
       g_form.setDisplay('country',true);
	   g_form.setMandatory('alternate_buyer',false)
	   g_form.setMandatory('first_payment_approval_display',false)
    }

    if (newValue == '2') {
       //display variables for tab 2
        g_form.setDisplay('computer_model', true);
		g_form.setMandatory('alternate_buyer',false)
		g_form.setMandatory('first_payment_approval_display',false)
    }
    if (newValue == '3') {
       //display variables for tab 3
        g_form.setDisplay('justification', true);
        g_form.setMandatory('alternate_buyer',false)
		g_form.setMandatory('first_payment_approval_display',false)
    }
	if (newValue == '4') {
       //display variables for tab 4
        g_form.setDisplay('due_date', true);
		g_form.setMandatory('alternate_buyer',false)
		g_form.setMandatory('first_payment_approval_display',false)
    }
	if (newValue == '5') {
       //display variables for tab 5
        g_form.setDisplay('requested_by', true);
		g_form.setDisplay('alternate_buyer', true);
		g_form.setDisplay('first_payment_approval_display', true);
		g_form.setMandatory('alternate_buyer',true);
		g_form.setMandatory('first_payment_approval_display',true)
    }
}
function setToHiden() {
	g_form.addInfoMessage("onchage");
   //Type appropriate comment here, and begin script below
   g_form.setDisplay('first_payment_approval_display',false);
   g_form.setDisplay('company',false);
   g_form.setDisplay('requested_by',false);
   g_form.setDisplay('due_date',false);
   g_form.setDisplay('alternate_buyer',false);
   g_form.setDisplay('justification',false);
   g_form.setDisplay('country',false);
   g_form.setDisplay('geo',false);
   g_form.setDisplay('computer_model',false);
   g_form.setMandatory('first_payment_approval_display',false)
   g_form.setMandatory('alternate_buyer',false)
}
